<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import AdminPageShell from './AdminPageShell.vue'
import { promptApi } from '@/api/promptApi'
import type { PromptEntry, PromptVersion, PromptReleaseLog, PromptVersionCompare } from '@/types/admin'
import type { PageResponse } from '@/types/api'
const query = reactive({ pageNo: 1, pageSize: 10, keyword: '' }); const result = ref<PageResponse<PromptEntry>>({ data: [], pageNo: 1, pageSize: 10, totalCount: 0, totalPage: 0, success: true }); const versions = ref<PromptVersion[]>([]); const logs = ref<PromptReleaseLog[]>([]); const selected = ref<PromptEntry>(); const compareResult = ref<PromptVersionCompare>(); const loading = ref(false)
async function load() { loading.value = true; try { result.value = await promptApi.query(query) } catch (e) { ElMessage.error(e instanceof Error ? e.message : 'Prompt 加载失败') } finally { loading.value = false } }
async function select(row: PromptEntry) { selected.value = row; versions.value = await promptApi.versions(row.id); logs.value = await promptApi.releaseLogs(row.id) }
async function publish(version: PromptVersion) { if (!selected.value) return; const reason = await ElMessageBox.prompt('请输入发布原因', '发布 Prompt', { inputValidator: (value) => value.trim() ? true : '请输入原因' }); await promptApi.publish(selected.value.id, version.id, reason.value); ElMessage.success('发布成功'); select(selected.value) }
async function offline() { if (!selected.value) return; const reason = await ElMessageBox.prompt('请输入下线原因', '下线 Prompt', { inputValidator: (value) => value.trim() ? true : '请输入原因' }); await promptApi.offline(selected.value.id, reason.value); ElMessage.success('已下线'); select(selected.value) }
async function rollback(version: PromptVersion) { if (!selected.value) return; const reason = await ElMessageBox.prompt('请输入回滚原因', '回滚 Prompt', { inputValidator: (value) => value.trim() ? true : '请输入原因' }); await promptApi.rollback(selected.value.id, version.id, reason.value); ElMessage.success('回滚成功'); select(selected.value) }
async function compare() { if (!selected.value || versions.value.length < 2) return; const [left, right] = versions.value; compareResult.value = await promptApi.compare(selected.value.id, left.id, right.id) }
onMounted(load)
</script>
<template><AdminPageShell eyebrow="PROMPT OPERATIONS" title="Prompt 管理" description="查看版本变化，谨慎发布影响 Agent 行为的提示词。"><el-card><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="搜索 Prompt" @keyup.enter="load" /><el-button type="primary" @click="load">查询</el-button></div><el-table v-loading="loading" :data="result.data" row-key="id" @row-click="select"><el-table-column prop="promptName" label="名称" min-width="180" /><el-table-column prop="promptKey" label="Key" min-width="170" /><el-table-column prop="agentCapability" label="Agent 能力" min-width="160" /><el-table-column prop="status" label="状态" width="110" /><el-table-column prop="updateTime" label="更新时间" min-width="170" /></el-table><el-pagination v-model:current-page="query.pageNo" v-model:page-size="query.pageSize" layout="total, prev, pager, next" :total="result.totalCount" @current-change="load" /></el-card><el-card v-if="selected" class="version-card"><template #header><div class="version-header"><strong>{{ selected.promptName }} · 版本</strong><div><el-button text @click="compare">比较</el-button><el-button text type="warning" @click="offline">下线</el-button><el-button text @click="selected = undefined">关闭</el-button></div></div></template><el-empty v-if="!versions.length" description="暂无版本" /><div v-for="version in versions" :key="version.id" class="version-row"><div><strong>v{{ version.versionNo }}</strong><el-tag size="small" :type="version.current ? 'success' : 'info'">{{ version.versionStatus || 'DRAFT' }}</el-tag><p>{{ version.changeReason || '暂无变更说明' }}</p></div><div><el-button v-if="!version.current" type="primary" plain @click="publish(version)">发布</el-button><el-button v-if="!version.current" link type="warning" @click="rollback(version)">回滚</el-button></div></div><el-divider v-if="logs.length" content-position="left">发布审计</el-divider><div v-for="log in logs" :key="log.id" class="audit-row"><span>{{ log.operationType }}</span><span>{{ log.operationReason || log.failureReason || '无原因' }}</span><span>{{ log.createTime || '暂无时间' }}</span></div><div v-if="compareResult" class="compare-grid"><div><strong>左版本</strong><pre>{{ compareResult.leftPromptContent }}</pre></div><div><strong>右版本</strong><pre>{{ compareResult.rightPromptContent }}</pre></div></div></el-card></AdminPageShell></template>
<style scoped>.toolbar { display: flex; gap: 10px; margin-bottom: 18px; }.toolbar .el-input { max-width: 300px; }.el-pagination { justify-content: flex-end; margin-top: 18px; }.version-card { margin-top: 18px; }.version-header, .version-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }.version-row { padding: 13px 0; border-bottom: 1px solid #edf2f0; }.version-row:last-child { border-bottom: 0; }.version-row strong { margin-right: 10px; color: #24483f; }.version-row p { margin: 5px 0 0; color: #7b8a85; font-size: 12px; }.audit-row { display: grid; grid-template-columns: 120px 1fr 160px; gap: 10px; padding: 8px 0; border-bottom: 1px solid #edf2f0; color: #687b75; font-size: 12px; }.compare-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 18px; }.compare-grid pre { max-height: 220px; overflow: auto; padding: 12px; border-radius: 6px; background: #102a27; color: #e7f4ef; white-space: pre-wrap; } @media (max-width: 700px) { .compare-grid { grid-template-columns: 1fr; }.audit-row { grid-template-columns: 1fr; } }</style>
